import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { SqlitedatabaseService } from 'src/app/services/sqlite/sqlitedatabase.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-uniform-schoollist',
  templateUrl: './uniform-schoollist.page.html',
  styleUrls: ['./uniform-schoollist.page.scss'],
})
export class UniformSchoollistPage implements OnInit {
  schoolListData: any=[];
  routeData: any;
  emis_username: any;

  constructor(private router: Router,private route: ActivatedRoute,private usersessionService: UserSessionService,
    private sqliteDB: SqlitedatabaseService) {
    this.emis_username = this.usersessionService.emis_username();
     }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.onSelectTotalSec()
  }

  navigateBack() {
    this.router.navigate(['/tabs/home']);
  }

  getServerData() {
    this.schoolListData = []
    // fetch('https://d1wpyxz35bzzz4.cloudfront.net/Uniform_schemes_volu_map_'+this.emis_username+'_stage.json').then(res => res.json()).then(manage => {
    fetch('https://d1wpyxz35bzzz4.cloudfront.net/Uniform_schemes_volu_map_'+this.emis_username+'.json').then(res => res.json()).then(manage => {
      if(manage.length > 0){
        const final = manage
        this.schoolListData = [];
        this.schoolListData = final
        this.insertLocalData(final)
      }
    })
  }

  insertLocalData(elementData) {
    let insertRows = [];
    elementData.forEach(element => {
      insertRows.push([
        "INSERT INTO uniformschoollists VALUES (?,?,?,?,?,?,?,?)",
        [null, element.school_id, element.school_name, element.udise_code, element.region, element.total_students, element.Meals_eating, element.measurement_completed]
      ]);
    });
    this.sqliteDB.bulkInsert(insertRows).then((result) => {
      this.onSelectTotalSec()
      console.info("school list LocalData Stored Locally");
    })
  }

  onSelectTotalSec(){
    this.schoolListData = []
    let manage = []
    let query = 'SELECT * FROM uniformschoollists';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      if (data.rows.length > 0) {
        for (var i = 0; i < data.rows.length; i++) {
          manage.push(data.rows.item(i));
      }
      this.schoolListData = manage

      this.schoolListData.sort((a, b) => {
        const nameA = a.school_name.toLowerCase();
        const nameB = b.school_name.toLowerCase();
        if (nameA < nameB) {
            return -1; // Name A comes before Name B
        }
        if (nameA > nameB) {
            return 1; // Name A comes after Name B
        }
        return 0; // Names are equal
    });

      } else {
        console.log("in server");
        this.getServerData()
      }
    })
  }

  navigateNext(schoolName,schoolId,region,item) {
    let measurement_completed = item.measurement_completed
    this.router.navigate(['/tabs/uniform-classlist'], { queryParams : {"schoolName": schoolName,"schoolId": schoolId,"region": region,"measurement_completed": measurement_completed} });
  }

  handleRefresh(event){
    let query = 'DELETE FROM uniformschoollists';
    return this.sqliteDB.getDataLocalDB(query).then(data => {
      fetch('https://d1wpyxz35bzzz4.cloudfront.net/Uniform_schemes_volu_map_'+this.emis_username+'.json').then(res => res.json()).then(manage => {
      if(manage.length > 0)  {
        this.schoolListData = [];
        const final = manage
        this.schoolListData = final
        event.target.complete();
        this.insertLocalData(final)
      }
      })
    })
  }

}
